export function shippingCost(weightKg: number): number {
  // Flat rate up to 2 kg
  if (weightKg <= 2) return 499;
  // Then 1.50 per extra kg
  return 499 + Math.ceil(weightKg - 2) * 150;
}

files.headContent:
export function shippingCost(weightKg: number): number {
  // Parcels up to 2 kg pay the flat rate of 4.99 EUR (in cents)
  if (weightKg <= 2) return 499;
  // Every started kilogram above that adds 1.50 EUR
  return 499 + Math.ceil(weightKg - 2) * 150;
}
